#nullable enable

using Alba;
using JasperFx.Core;
using Marten.Events;
using Allocation.Contracts;
using Allocation.Slices.Allocation;
using Allocation.Views;
using Shouldly;
using Xunit;

namespace Allocation.IntegrationTests.Slices.Allocation;

/// <summary>
/// Given/Thens, not GWTs: a read model only reads events that already exist, so there is no command to be
/// the WHEN. Pattern: state-view. Status: ready. LIVE, so every test here must pass.
///
/// Asserted THROUGH THE READ ENDPOINT rather than against the document store, which covers the projection
/// and the query surface — what a caller actually gets.
///
/// This view is Async, so every test WAITS where an Inline one would simply read. That cost is the whole
/// reason the two todo Views next door are registered Inline instead: a human can wait, and a processor's
/// liveness cannot.
/// </summary>
public sealed class PoolAvailabilityTests(AppFixture fixture) : IntegrationContext(fixture)
{
    private static string PoolStream => OpenPoolState.StreamKey(SeedData.PoolId.ToString());
    private static string SlotStream(int n) => ReserveSlotState.StreamKey(SeedData.PoolId, n);
    private static string GrantStream(Guid g) => IssueGrantState.StreamKey(g.ToString());

    private async Task<PoolAvailability> Availability()
    {
        // Marten.Events.TestingExtensions — no doc page states that namespace. Asserting without the wait
        // fails intermittently and looks exactly like a broken projection.
        await Store.WaitForNonStaleProjectionDataAsync(10.Seconds());

        var (_, result) = await WhenPosting(x =>
        {
            x.Get.Url($"/pools/{SeedData.PoolId}/availability");
            x.StatusCodeShouldBe(200);
        });
        return await result.ReadAsJsonAsync<PoolAvailability>()
               ?? throw new InvalidOperationException("no availability row in the response body");
    }

    // A pool nobody has reserved from shows all of its capacity
    //   GIVEN Pool Opened(capacity=3)
    //   THEN  PoolAvailability(capacity=3, taken=0, remaining=3)
    [Fact]
    public async Task APoolNobodyHasReservedFromShowsAllOfItsCapacity()
    {
        await Given(PoolStream, new PoolOpened(SeedData.PoolId, 3, SeedData.SeededAt));

        var row = await Availability();

        row.Capacity.ShouldBe(3);
        row.Taken.ShouldBe(0);
        row.Remaining.ShouldBe(3);
        row.TakenSlots.ShouldBeEmpty();
    }

    // A reserved slot is taken, and is named
    //   GIVEN Pool Opened(capacity=3), Slot Reserved(slotNumber=1)
    //   THEN  PoolAvailability(taken=1, remaining=2, takenSlots=1)
    [Fact]
    public async Task AReservedSlotIsTakenAndIsNamed()
    {
        await Given(PoolStream, new PoolOpened(SeedData.PoolId, 3, SeedData.SeededAt));
        await Given(SlotStream(1), new SlotReserved(SeedData.PoolId, 1, SeedData.GrantId, SeedData.SeededAt));

        var row = await Availability();

        row.Taken.ShouldBe(1);
        row.Remaining.ShouldBe(2);
        // NAMED, not just counted. The reserver's opening guess comes from this list, so a count alone
        // would leave it with nothing to guess from — and the model says takenSlots for that reason.
        row.TakenSlots.ShouldBe([1]);
    }

    // A released slot goes back into the pool
    //   GIVEN Pool Opened(capacity=3), Slot Reserved(slotNumber=1), Slot Released(slotNumber=1)
    //   THEN  PoolAvailability(taken=0, remaining=3)
    [Fact]
    public async Task AReleasedSlotGoesBackIntoThePool()
    {
        await Given(PoolStream, new PoolOpened(SeedData.PoolId, 3, SeedData.SeededAt));
        await Given(SlotStream(1),
            new SlotReserved(SeedData.PoolId, 1, SeedData.GrantId, SeedData.SeededAt),
            new SlotReleased(SeedData.PoolId, 1, SeedData.GrantId, "TheWorkRefused", SeedData.SeededAt));

        var row = await Availability();

        row.Taken.ShouldBe(0);
        row.Remaining.ShouldBe(3);
        row.TakenSlots.ShouldBeEmpty();
    }

    // Issuing a grant against an already reserved slot consumes no further capacity
    //   GIVEN Pool Opened(capacity=3), Slot Reserved(slotNumber=1), Grant Issued(slotNumber=1)
    //   THEN  PoolAvailability(taken=1, remaining=2)
    [Fact]
    public async Task IssuingAGrantAgainstAnAlreadyReservedSlotConsumesNoFurtherCapacity()
    {
        await Given(PoolStream, new PoolOpened(SeedData.PoolId, 3, SeedData.SeededAt));
        await Given(SlotStream(1), new SlotReserved(SeedData.PoolId, 1, SeedData.GrantId, SeedData.SeededAt));
        await Given(GrantStream(SeedData.GrantId),
            new GrantIssued(SeedData.GrantId, SeedData.PoolId, 1, SeedData.SeededAt));

        var row = await Availability();

        // WHAT THE VIEW IGNORES, and it is the one thing this projection can get wrong that nothing else
        // would notice. The RESERVATION costs a unit; the execution costs nothing. The drawing already
        // claims that — Grant Issued has no edge to this view — and this is the only place the claim is
        // executable. Wire GrantIssued into the fold and exactly this test fails.
        row.Taken.ShouldBe(1);
        row.Remaining.ShouldBe(2);
        row.TakenSlots.ShouldBe([1]);
    }
}
